const STORIES=[{"u": 3, "t": "您是老师吗？", "tv": "Bạn là giáo viên à?", "s": [["大卫是美国学生。", "David là sinh viên người Mỹ."], ["大卫：“您好！您是老师吗？”", "David: “Chào chị! Chị là giáo viên ạ?”"], ["王方：“不是，不是！我是学生。”", "Vương Phương: “Không phải, không phải! Mình là sinh viên.”"], ["大卫：“对不起！我叫大卫。你叫什么名字？”", "David: “Xin lỗi nhé! Mình tên là David. Bạn tên là gì?”"], ["王方：“没关系。我叫王方，我是中国人。”", "Vương Phương: “Không sao. Mình tên là Vương Phương, mình là người Trung Quốc.”"], ["大卫：“你好，王方！”", "David: “Chào bạn, Vương Phương!”"], ["李月：“你们好！”", "Lý Nguyệt: “Chào các em!”"], ["大卫：“你好！你是学生吗？你叫什么名字？”", "David: “Chào bạn! Bạn là sinh viên à? Bạn tên là gì?”"], ["李月：“我叫李月。我不是学生，我是老师。”", "Lý Nguyệt: “Tôi tên là Lý Nguyệt. Tôi không phải sinh viên, tôi là giáo viên.”"], ["大卫：“对不起，李老师！”", "David: “Em xin lỗi, cô Lý!”"], ["李月：“没关系。你是美国人吗？”", "Lý Nguyệt: “Không sao. Em là người Mỹ à?”"], ["大卫：“是，我是美国人。谢谢老师！再见！”", "David: “Dạ vâng, em là người Mỹ. Em cảm ơn cô! Chào cô ạ!”"]], "q": [{"q": "David là người nước nào?", "o": ["Người Trung Quốc", "Người Mỹ", "Người Việt Nam", "Người Anh"], "a": 1}, {"q": "Vương Phương thật ra là ai?", "o": ["Giáo viên", "Bác sĩ", "Sinh viên", "Bạn của Lý Nguyệt"], "a": 2}, {"q": "David đã nhầm Lý Nguyệt là gì?", "o": ["Sinh viên", "Giáo viên", "Người Mỹ", "Bạn học cũ"], "a": 0}]}, {"u": 5, "t": "她叫什么名字？", "tv": "Con bé tên là gì?", "s": [["玛丽是美国人，她是学生。", "Mary là người Mỹ, cô ấy là sinh viên."], ["李月是她的中国朋友。", "Lý Nguyệt là bạn người Trung Quốc của cô ấy."], ["玛丽：“李月，你家有几口人？”", "Mary: “Lý Nguyệt, nhà cậu có mấy người?”"], ["李月：“我家有三口人。”", "Lý Nguyệt: “Nhà mình có ba người.”"], ["玛丽：“你有女儿吗？”", "Mary: “Cậu có con gái không?”"], ["李月：“有，我有女儿。”", "Lý Nguyệt: “Có, mình có một đứa con gái.”"], ["玛丽：“她今年几岁了？”", "Mary: “Năm nay bé mấy tuổi rồi?”"], ["李月：“她今年五岁了。”", "Lý Nguyệt: “Năm nay bé năm tuổi rồi.”"], ["玛丽：“她叫什么名字？”", "Mary: “Bé tên là gì?”"], ["李月：“她叫玛丽。”", "Lý Nguyệt: “Bé tên là Mary.”"], ["玛丽：“她叫玛丽？玛丽是我的名字！”", "Mary: “Bé tên là Mary á? Mary là tên của mình mà!”"], ["李月：“对，你是我的好朋友！”", "Lý Nguyệt: “Đúng vậy, vì cậu là bạn thân của mình mà!”"]], "q": [{"q": "Nhà Lý Nguyệt có mấy người?", "o": ["Hai người", "Bốn người", "Năm người", "Ba người"], "a": 3}, {"q": "Con gái Lý Nguyệt năm nay mấy tuổi?", "o": ["Ba tuổi", "Năm tuổi", "Mười tuổi", "Bốn tuổi"], "a": 1}, {"q": "Vì sao Mary ngạc nhiên?", "o": ["Con gái Lý Nguyệt trùng tên với cô", "Lý Nguyệt không có con", "Con gái Lý Nguyệt là người Mỹ", "Lý Nguyệt là giáo viên của cô"], "a": 0}]}, {"u": 7, "t": "大卫会读吗？", "tv": "David có biết đọc không?", "s": [["小明是中国人，大卫是他的美国同学。", "Tiểu Minh là người Trung Quốc, David là bạn học người Mỹ của cậu."], ["星期六，大卫去小明家。", "Thứ Bảy, David đến nhà Tiểu Minh."], ["小明的妈妈做了很多菜。", "Mẹ Tiểu Minh nấu rất nhiều món."], ["妈妈问：“大卫，你会说汉语吗？”", "Mẹ hỏi: “David, cháu có biết nói tiếng Trung không?”"], ["大卫：“会！我会说汉语，我会写汉字。”", "David: “Dạ có! Cháu biết nói tiếng Trung, cháu còn biết viết chữ Hán nữa.”"], ["妈妈写了“菜”字，问：“你会读吗？”", "Mẹ viết chữ “菜” rồi hỏi: “Cháu có biết đọc chữ này không?”"], ["大卫看了看，说：“我会！是‘菜’。”", "David nhìn một lúc rồi nói: “Cháu biết ạ! Là chữ ‘cài’ (món ăn).”"], ["妈妈说：“你的汉语很好！”", "Mẹ nói: “Tiếng Trung của cháu giỏi quá!”"], ["小明说：“大卫会读‘菜’，会写‘菜’。”", "Tiểu Minh nói: “David biết đọc chữ ‘món ăn’, biết viết chữ ‘món ăn’.”"], ["妈妈：“你会吃菜吗？”", "Mẹ: “Thế cháu có biết ăn món ăn không?”"], ["大卫：“会！我很会吃！”", "David: “Dạ có! Khoản ăn thì cháu giỏi nhất!”"], ["妈妈说：“好，请吃！”", "Mẹ nói: “Được, mời cháu ăn nào!”"]], "q": [{"q": "David đến nhà Tiểu Minh vào ngày nào?", "o": ["Chủ nhật", "Thứ Hai", "Thứ Bảy", "Thứ Sáu"], "a": 2}, {"q": "Mẹ Tiểu Minh viết chữ gì cho David đọc?", "o": ["Chữ “菜” (món ăn)", "Chữ “书” (sách)", "Chữ “字” (chữ)", "Tên của David"], "a": 0}, {"q": "Cuối truyện David nói mình giỏi việc gì?", "o": ["Viết chữ Hán", "Nấu ăn", "Đọc sách", "Ăn"], "a": 3}]}, {"u": 9, "t": "小猫在哪儿？", "tv": "Mèo con ở đâu?", "s": [["小明的爸爸是医生，他在医院工作。", "Bố Tiểu Minh là bác sĩ, ông làm việc ở bệnh viện."], ["小明家有小猫，有小狗。", "Nhà Tiểu Minh có một chú mèo con và một chú chó con."], ["星期天下午，爸爸不工作。", "Chiều Chủ nhật, bố không phải đi làm."], ["小明：“爸爸，我的小猫呢？”", "Tiểu Minh: “Bố ơi, mèo con của con đâu rồi?”"], ["爸爸：“在椅子下面吗？”", "Bố: “Có ở dưới ghế không?”"], ["小明看了看：“椅子下面没有。”", "Tiểu Minh nhìn thử: “Dưới ghế không có ạ.”"], ["爸爸：“在你妈妈那儿吗？”", "Bố: “Có ở chỗ mẹ con không?”"], ["小明：“不在。妈妈在商店买杯子。”", "Tiểu Minh: “Không ạ. Mẹ đang ở cửa hàng mua cốc.”"], ["爸爸：“小狗呢？小狗在哪儿？”", "Bố: “Thế chó con đâu? Chó con ở đâu?”"], ["小明：“小狗在那儿！”", "Tiểu Minh: “Chó con ở đằng kia!”"], ["小明看了看小狗：“爸爸，小猫在小狗下面！”", "Tiểu Minh nhìn chó con: “Bố ơi, mèo con nằm dưới chó con kìa!”"], ["爸爸说：“小猫是小狗的好朋友！”", "Bố nói: “Mèo con là bạn thân của chó con đấy!”"]], "q": [{"q": "Bố Tiểu Minh làm nghề gì?", "o": ["Giáo viên", "Bác sĩ", "Bán hàng", "Tài xế"], "a": 1}, {"q": "Mẹ Tiểu Minh đang ở đâu?", "o": ["Ở bệnh viện", "Ở trường học", "Ở nhà", "Ở cửa hàng mua cốc"], "a": 3}, {"q": "Cuối cùng mèo con ở đâu?", "o": ["Dưới ghế", "Ở chỗ mẹ", "Dưới chó con", "Trong cửa hàng"], "a": 2}]}, {"u": 11, "t": "三点十分的电影", "tv": "Bộ phim lúc ba giờ mười", "s": [["大卫和玛丽住在北京。", "David và Mary sống ở Bắc Kinh."], ["星期六中午，他们在大卫家吃饭。", "Trưa thứ Bảy, họ ăn cơm ở nhà David."], ["大卫：“下午我们去看电影，好吗？”", "David: “Chiều nay chúng mình đi xem phim nhé?”"], ["玛丽：“好！电影几点？”", "Mary: “Được đấy! Phim chiếu lúc mấy giờ?”"], ["大卫看了看电脑：“下午三点十分。”", "David xem máy tính: “Ba giờ mười chiều.”"], ["吃了饭，他们去了电影院。", "Ăn cơm xong, họ đến rạp chiếu phim."], ["三点，他们坐在电影院里。", "Ba giờ, họ đã ngồi trong rạp."], ["电影院里没有人。", "Trong rạp không có ai cả."], ["玛丽：“前面没有人，后面没有人，人呢？”", "Mary: “Phía trước không có ai, phía sau cũng không có ai, mọi người đâu hết rồi?”"], ["大卫：“请问，三点十分的电影呢？”", "David: “Xin hỏi, phim lúc ba giờ mười đâu ạ?”"], ["一个人说：“三点十分的电影？是明天！”", "Một người nói: “Phim ba giờ mười ấy à? Là ngày mai cơ!”"], ["大卫：“明天？对不起，玛丽……”", "David: “Ngày mai á? Xin lỗi nhé, Mary…”"], ["玛丽：“没关系！明天我们再去看。三点十分，我看电脑！”", "Mary: “Không sao! Mai mình lại đi xem. Lần này để mình xem máy tính!”"]], "q": [{"q": "David và Mary ăn trưa ở đâu?", "o": ["Ở nhà David", "Ở nhà hàng", "Ở rạp chiếu phim", "Ở trường"], "a": 0}, {"q": "Vì sao trong rạp không có ai?", "o": ["Phim đã chiếu xong", "Phim chiếu vào ngày mai", "Rạp đóng cửa", "Họ đến sai rạp"], "a": 1}, {"q": "Mary định làm gì vào ngày mai?", "o": ["Ở nhà ăn cơm", "Đi mua máy tính", "Không đi xem phim nữa", "Tự xem giờ chiếu trên máy tính"], "a": 3}]}, {"u": 13, "t": "张东在学习呢", "tv": "Trương Đông đang học bài", "s": [["星期天上午，天气太冷了。", "Sáng Chủ nhật, trời lạnh quá."], ["张东在家看电视呢。", "Trương Đông đang ở nhà xem tivi."], ["他很喜欢看电视，不喜欢学习。", "Cậu rất thích xem tivi, không thích học bài."], ["十点，王方给他打电话。", "Mười giờ, Vương Phương gọi điện cho cậu."], ["“喂，张东，你在做什么呢？”", "“Alô, Trương Đông, cậu đang làm gì đấy?”"], ["“我……我在学习汉语呢。”", "“Mình… mình đang học tiếng Trung.”"], ["“太好了！我也想学习，我能去你家吗？”", "“Hay quá! Mình cũng muốn học, mình đến nhà cậu được không?”"], ["“能，能！你来吧。”", "“Được, được! Cậu đến đi.”"], ["张东不看电视了，他坐在桌子前面看书。", "Trương Đông tắt tivi, ngồi vào bàn mở sách ra đọc."], ["王方来了，他给张东买了一些水果。", "Vương Phương đến, cậu ấy mua cho Trương Đông ít hoa quả."], ["王方看了看电视：“张东，你的电视怎么这么热？”", "Vương Phương nhìn cái tivi: “Trương Đông, sao tivi nhà cậu nóng thế?”"], ["张东：“我……我的电视也喜欢学习汉语！”", "Trương Đông: “Mình… tivi nhà mình cũng thích học tiếng Trung mà!”"]], "q": [{"q": "Lúc Vương Phương gọi điện, Trương Đông thật ra đang làm gì?", "o": ["Học tiếng Trung", "Xem tivi", "Ngủ", "Ăn hoa quả"], "a": 1}, {"q": "Vương Phương mang gì đến nhà Trương Đông?", "o": ["Sách", "Trà", "Hoa quả", "Cốc"], "a": 2}, {"q": "Vương Phương phát hiện điều gì?", "o": ["Trương Đông cầm sách ngược", "Tivi vẫn còn nóng", "Trương Đông đang ngủ", "Trương Đông không có sách"], "a": 1}]}, {"u": 15, "t": "开出租车的先生", "tv": "Bác tài xế taxi", "s": [["玛丽是美国人。", "Mary là người Mỹ."], ["上个月，她是坐飞机来北京的。", "Tháng trước, cô ấy đi máy bay đến Bắc Kinh."], ["下了飞机，她坐出租车去饭店。", "Xuống máy bay, cô ấy đi taxi về khách sạn."], ["开车的先生问她：“你会说汉语吗？”", "Bác tài xế hỏi cô: “Cô có biết nói tiếng Trung không?”"], ["玛丽：“会一点儿。我是在美国的大学学的。”", "Mary: “Cháu biết một chút ạ. Cháu học ở trường đại học bên Mỹ.”"], ["先生很高兴：“你的汉语很好啊！你的老师是谁？”", "Bác tài rất vui: “Tiếng Trung của cô hay đấy! Thầy cô của cô là ai?”"], ["玛丽：“我的老师是中国人，他叫王方。”", "Mary: “Thầy giáo cháu là người Trung Quốc, thầy tên là Vương Phương.”"], ["先生听了，问：“王方？他是哪年去美国的？”", "Bác tài nghe xong liền hỏi: “Vương Phương à? Cậu ấy sang Mỹ năm nào?”"], ["玛丽：“他是二〇一八年去的。”", "Mary: “Thầy ấy sang năm 2018 ạ.”"], ["先生：“王方是我儿子啊！”", "Bác tài: “Vương Phương là con trai tôi đấy!”"], ["玛丽：“是吗？太好了！”", "Mary: “Thật ạ? Tuyệt quá!”"], ["二十分钟后，玛丽下了车。", "Hai mươi phút sau, Mary xuống xe."], ["先生给了她一些苹果：“这些苹果给你。明天我们一起吃饭，我给王方打电话！”", "Bác tài đưa cho cô mấy quả táo: “Táo này cho cô. Mai chúng ta cùng ăn cơm nhé, tôi sẽ gọi điện cho Vương Phương!”"]], "q": [{"q": "Mary đến Bắc Kinh bằng gì?", "o": ["Tàu hỏa", "Ô tô", "Taxi", "Máy bay"], "a": 3}, {"q": "Mary học tiếng Trung ở đâu?", "o": ["Ở một trường đại học bên Mỹ", "Ở Bắc Kinh", "Ở nhà bác tài", "Trên máy bay"], "a": 0}, {"q": "Bác tài xế có quan hệ gì với thầy giáo Vương Phương?", "o": ["Là thầy giáo của anh ấy", "Là bố của anh ấy", "Là bạn học của anh ấy", "Không quen biết"], "a": 1}]}];
